import sys, json
from pathlib import Path
sys.path.insert(0, 'scripts')
import pymupdf as fitz
from preprocess_mc import detect_labels

def build(year, extras=None):
    doc = fitz.open(f'paper/mc/{year}p1a.pdf')
    labels = {}
    for pi in range(1, doc.page_count):
        # skip likely non-content trailing pages with junk detections
        if pi >= 14:
            continue
        hits = detect_labels(doc[pi], 5.0, 33)
        for n, x, y in hits:
            if 1 <= n <= 33 and n not in labels:
                labels[n] = (pi, x, y)
    doc.close()
    if extras:
        labels.update(extras)
    missing = [n for n in range(1, 34) if n not in labels]
    if missing:
        raise SystemExit(f'{year} still missing {missing}')
    # sanity: monotonic page/y
    prev = (-1, -1)
    for n in range(1, 34):
        pi, x, y = labels[n]
        if (pi, y) < prev:
            print('WARN order', n, labels[n], 'after', prev)
        prev = (pi, y)
    ov = {str(n): [int(pi), round(float(x), 2), round(float(y), 2)] for n, (pi, x, y) in labels.items()}
    path = Path(f'scripts/overrides_{year}.json')
    path.write_text(json.dumps(ov, indent=2) + '\n')
    print('wrote', path, 'n=', len(ov))
    return ov

