data = json.loads(Path('.lavish/classified-review/data.json').read_text())
sections = data['sections']
total = sum(s['count'] for s in sections)

payload = {
    'sections': [
        {
            'num': s['num'], 'name': s['name'], 'book': s['book'], 'count': s['count'],
            'items': [
                {
                    'year': it['year'], 'q': it['q'], 'img': it['img'],
                    'sections': it['sections'], 'names': it['names'],
                    'primary': it['primary'], 'reason': it['reason'],
                    'preview': (it.get('preview') or '')[:180],
                    'is_primary': it['is_primary'],
                }
                for it in s['items']
            ],
        }
        for s in sections
    ]
}

books = []
for s in sections:
    if not books or books[-1]['name'] != s['book']:
        books.append({'name': s['book'], 'sections': []})
    books[-1]['sections'].append({'num': s['num'], 'name': s['name'], 'count': s['count']})

nav_html = []
for book in books:
    nav_html.append(f'<div class="nav-book">{escape(book["name"])}</div>')
    for s in book['sections']:
        nav_html.append(
            f'<button type="button" class="nav-sec" data-sec="{s["num"]}">'
            f'<span class="nav-sec-label"><span class="mono">S{s["num"]}</span> {escape(s["name"])}</span>'
            f'<span class="nav-count">{s["count"]}</span></button>'
        )

opts = ''.join(f'<option value="{s["num"]}">{s["num"]}. {escape(s["name"])}</option>' for s in sections)
payload_json = json.dumps(payload, ensure_ascii=False).replace('</', '<\\/')

