</head>
<body>
  <div class="marks-panel">
    <div class="marks-row">
      <div class="left">
        <span>Saved marks: <strong id="markCount">0</strong> (browser-local; survives reloads)</span>
        <button type="button" class="btn ghost" id="toggleMarks">Show list</button>
        <button type="button" class="btn ghost" id="copyMarks">Copy JSON</button>
        <button type="button" class="btn" id="sendMarks">Queue all marks to agent</button>
        <button type="button" class="btn ghost" id="clearMarks">Clear</button>
      </div>
    </div>
    <div class="marks-list" id="marksList"></div>
  </div>
  <div class="app">
    <aside class="sidebar">
      <div class="brand">
        <h1>Classification review</h1>
        <p>$total placements · leave Correct section empty if OK; pick a section only to reclassify.</p>
      </div>
      $nav_html
    </aside>
    <main class="main">
      <div class="help">
        Leave <strong>Correct section</strong> empty if the classification is fine. Choosing a section means it should move there.
        Use <strong>Crop / dropping issue</strong> when content is cut off, then tick top / right / bottom / left.
        Multi-section questions show <strong>primary</strong> plus <strong>also S…</strong> badges.
      </div>
      <div class="topbar">
        <div>
          <div class="meta" id="bookLabel">Select a section</div>
          <h2 id="secTitle">Choose a topic</h2>
        </div>
        <div class="pill" id="secCount">0 questions</div>
      </div>
      <div id="grid" class="grid"><p class="empty">Select a section to load its MC questions.</p></div>
    </main>
  </div>
  <div class="toast" id="toast" role="status"></div>
  <script id="payload" type="application/json">$payload_json</script>
  <script id="secmap" type="application/json">$sec_map_json</script>
  <script>
    const DATA = JSON.parse(document.getElementById('payload').textContent);
    const SEC_NAMES = JSON.parse(document.getElementById('secmap').textContent);
    const SECTION_OPTS = `$opts`;
    const MARKS_KEY = 'lavish-marks-v1:paper2db-classified';
    const MARGINS = ['top', 'right', 'bottom', 'left'];
    const grid = document.getElementById('grid');
    const secTitle = document.getElementById('secTitle');
    const bookLabel = document.getElementById('bookLabel');
    const secCount = document.getElementById('secCount');
    const toast = document.getElementById('toast');

    function showToast(msg) {
      toast.textContent = msg;
      toast.classList.add('show');
      clearTimeout(showToast._t);
      showToast._t = setTimeout(() => toast.classList.remove('show'), 1600);
    }
    function esc(s) {
      return String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    }
    function loadMarks() {
      try { return JSON.parse(localStorage.getItem(MARKS_KEY) || '[]'); } catch { return []; }
    }
    function saveMarks(marks) {
      localStorage.setItem(MARKS_KEY, JSON.stringify(marks));
      renderMarksBar();
    }
    function upsertMark(mark) {
      const marks = loadMarks().filter(m => !(String(m.year) === String(mark.year) && Number(m.question) === Number(mark.question)));
      marks.push(mark);
      marks.sort((a,b) => String(a.year).localeCompare(String(b.year)) || Number(a.question) - Number(b.question));
      saveMarks(marks);
    }
    function markSummary(m) {
      const bits = [];
      if (m.target) bits.push('class S' + m.current + '→S' + m.target);
      if (m.cropIssue) bits.push('crop ' + ((m.cropMargins || []).join('/') || '?'));
      if (m.note) bits.push(m.note);
      return bits.join(' · ') || 'flagged';
    }
    function renderMarksBar() {
      const marks = loadMarks();
      document.getElementById('markCount').textContent = String(marks.length);
      document.getElementById('marksList').innerHTML = marks.length
        ? marks.map(m => '<div>' + esc(m.year) + ' Q' + m.question + ': ' + esc(markSummary(m)) + '</div>').join('')
        : '<div>No marks yet.</div>';
    }
    function applyMarksToDom() {
      for (const m of loadMarks()) {
        const card = document.querySelector('#q-' + m.year + '-q' + m.question);
        const form = card && card.querySelector('form');
        if (!form) continue;
        if (m.target) form.target.value = String(m.target);
        if (m.note) form.note.value = m.note;
        form.cropIssue.checked = !!m.cropIssue;
        toggleCropBox(form);
        for (const side of MARGINS) {
          const el = form.querySelector('input[name="margin_' + side + '"]');
          if (el) el.checked = !!(m.cropMargins || []).includes(side);
        }
        if (m.cropIssue) card.classList.add('crop-bad');
        const btn = form.querySelector('button[type="submit"]');
        if (btn) { btn.classList.add('queued'); btn.textContent = 'Saved'; }
      }
    }
    function toggleCropBox(form) {
      const box = form.querySelector('.crop-box');
      if (!box) return;
      box.classList.toggle('open', !!form.cropIssue.checked);
    }
    function sectionBadges(it, viewingSec) {
      const all = String(it.sections).split(';').map(s => Number(s)).filter(Boolean);
      const primary = Number(it.primary);
      const badges = [];
      const pName = SEC_NAMES[String(primary)] || SEC_NAMES[primary] || '';
      badges.push('<span class="badge primary" title="' + esc(pName) + '">primary S' + primary + (pName ? ' · ' + esc(pName) : '') + '</span>');
      const others = all.filter(n => n !== primary);
      for (const n of others) {
        const name = SEC_NAMES[String(n)] || SEC_NAMES[n] || '';
        badges.push('<span class="badge secondary" title="' + esc(name) + '">also S' + n + (name ? ' · ' + esc(name) : '') + '</span>');
      }
      if (!it.is_primary) {
        badges.push('<span class="badge here">shown here as secondary</span>');
      }
      return badges.join('');
    }

    function renderSection(num) {
      const sec = DATA.sections.find(s => s.num === Number(num));
      if (!sec) return;
      document.querySelectorAll('.nav-sec').forEach(btn => {
        btn.classList.toggle('active', Number(btn.dataset.sec) === sec.num);
      });
      bookLabel.textContent = sec.book;
      secTitle.innerHTML = '<span class="mono">S' + sec.num + '</span> · ' + esc(sec.name);
      secCount.textContent = sec.count + ' questions';
      if (!sec.items.length) {
        grid.innerHTML = '<p class="empty">No questions in this section.</p>';
        return;
      }
      grid.innerHTML = sec.items.map(it => {
        const qid = it.year + '-q' + it.q;
        const reason = it.reason ? esc(it.reason) : '<span style="opacity:.6">No reason recorded</span>';
        const marginChecks = MARGINS.map(side =>
          '<label><input type="checkbox" name="margin_' + side + '" value="' + side + '" /> ' + side + '</label>'
        ).join('');
        return (
'<article class="card" id="q-' + qid + '">' +
  '<div class="card-head">' +
    '<div class="qid"><p class="year">Year ' + esc(it.year) + '</p><p class="qn">Q' + it.q + '</p></div>' +
    '<div class="badges">' + sectionBadges(it, sec.num) + '</div>' +
  '</div>' +
  '<div class="shot"><img src="' + esc(it.img) + '" alt="' + esc(it.year) + ' Q' + it.q + '" loading="lazy" /></div>' +
  '<div class="body">' +
    '<p class="preview">' + esc(it.preview) + '</p>' +
    '<p class="reason"><strong>LLM reason:</strong> ' + reason + '</p>' +
    '<form class="form" data-lavish-question="fix-' + qid + '" onsubmit="return queueFix(event)">' +
      '<input type="hidden" name="year" value="' + esc(it.year) + '" />' +
      '<input type="hidden" name="question" value="' + it.q + '" />' +
      '<input type="hidden" name="current" value="' + sec.num + '" />' +
      '<label class="field"><span>Correct section (leave empty if OK)</span><select name="target"><option value="">OK as classified</option>' + SECTION_OPTS + '</select></label>' +
      '<div class="row">' +
        '<input type="checkbox" name="cropIssue" id="crop-' + qid + '" onchange="toggleCropBox(this.form)" />' +
        '<label for="crop-' + qid + '">Crop / dropping issue</label>' +
      '</div>' +
      '<div class="crop-box">' +
        '<div class="label">Which margin is cut off? (select all that apply)</div>' +
        '<div class="margins">' + marginChecks + '</div>' +
      '</div>' +
      '<label class="field"><span>Note (optional)</span><input type="text" name="note" placeholder="e.g. option D cut off" /></label>' +
      '<div class="actions"><button type="submit" class="btn">Queue fix</button></div>' +
    '</form>' +
  '</div>' +
'</article>'
        );
      }).join('');
      history.replaceState(null, '', '#sec-' + sec.num);
      applyMarksToDom();
    }

    function queueFix(event) {
      event.preventDefault();
      const form = event.currentTarget;
      const year = form.year.value;
      const question = Number(form.question.value);
      const current = Number(form.current.value);
      const target = form.target.value ? Number(form.target.value) : null;
      const note = (form.note.value || '').trim();
      const cropIssue = form.cropIssue.checked;
      const cropMargins = MARGINS.filter(side => form['margin_' + side] && form['margin_' + side].checked);
      if (!target && !note && !cropIssue) {
        alert('Pick a correct section, tick Crop / dropping issue, or add a note.');
        return false;
      }
      if (cropIssue && !cropMargins.length) {
        alert('Crop / dropping issue is ticked - select at least one margin: top, right, bottom, or left.');
        return false;
      }
      const wrong = !!target;
      const mark = { year, question, current, target, note, wrong, cropIssue, cropMargins, at: new Date().toISOString() };
      upsertMark(mark);
      const card = form.closest('.card');
      if (card) card.classList.toggle('crop-bad', cropIssue);

      if (window.lavish && typeof window.lavish.queuePrompt === 'function') {
        const parts = [];
        if (target) {
          parts.push('Fix classification for ' + year + ' Q' + question + '.');
          parts.push('Currently shown under section ' + current + '.');
          parts.push('Move it to section ' + target + '.');
          parts.push('Do not patch only this item. Fix the classifier so this failure mode cannot recur, and check regressions.');
        }
        if (cropIssue) {
          parts.push('Crop / dropping issue for ' + year + ' Q' + question + ': content is cut off on the ' + cropMargins.join(', ') + ' margin(s).');
          parts.push('Fix the crop/anchor pipeline so this edge-cutoff pattern cannot recur on other questions.');
        }
        if (note) parts.push('Reviewer note: ' + note);
        window.lavish.queuePrompt(parts.join(' '), {
          tag: cropIssue && !target ? 'crop-issue' : 'reclassify',
          text: cropIssue && !target
            ? (year + ' Q' + question + ' crop ' + cropMargins.join('/'))
            : (year + ' Q' + question + ' → ' + (target || '?')),
          element: form,
          queueKey: 'fix-' + year + '-q' + question,
          data: mark
        });
      }
      const btn = form.querySelector('button[type="submit"]');
      if (btn) { btn.classList.add('queued'); btn.textContent = 'Saved'; }
      showToast('Saved ' + year + ' Q' + question);
      return false;
    }

    document.querySelectorAll('.nav-sec').forEach(btn => {
      btn.addEventListener('click', () => renderSection(btn.dataset.sec));
    });
    document.getElementById('toggleMarks').addEventListener('click', () => {
      const list = document.getElementById('marksList');
      const open = list.classList.toggle('open');
      document.getElementById('toggleMarks').textContent = open ? 'Hide list' : 'Show list';
    });
    document.getElementById('copyMarks').addEventListener('click', async () => {
      const text = JSON.stringify(loadMarks(), null, 2);
      try { await navigator.clipboard.writeText(text); showToast('Copied marks JSON'); }
      catch { prompt('Copy these marks:', text); }
    });
    document.getElementById('clearMarks').addEventListener('click', () => {
      if (confirm('Clear all saved marks in this browser?')) saveMarks([]);
    });
    document.getElementById('sendMarks').addEventListener('click', () => {
      const marks = loadMarks();
      if (!marks.length) { alert('No saved marks yet.'); return; }
      if (!window.lavish || typeof window.lavish.queuePrompt !== 'function') {
        alert('Lavish API unavailable. Use Copy JSON and paste into chat.');
        return;
      }
      const lines = marks.map(m => {
        const bits = [m.year + ' Q' + m.question];
        if (m.target) bits.push('class S' + m.current + '→S' + m.target);
        if (m.cropIssue) bits.push('crop ' + (m.cropMargins || []).join('/'));
        if (m.note) bits.push('note: ' + m.note);
        return bits.join(' | ');
      });
      const promptText = [
        'Here is my full list of review marks (misclassification and/or crop dropping issues).',
        'Do NOT fix them one-by-one with overrides only.',
        'Update the underlying method so these failure modes cannot recur on unmarked questions, and verify no regression on already-correct outputs.',
        'Marks:',
        ...lines,
        'Raw JSON:',
        JSON.stringify(marks)
      ].join('\n');
      window.lavish.queuePrompt(promptText, {
        tag: 'review-batch', text: marks.length + ' review marks',
        queueKey: 'review-batch', data: { marks }
      });
      showToast('Queued ' + marks.length + ' marks');
    });

    renderMarksBar();
    const hash = Number((location.hash.match(/sec-(\d+)/) || [])[1]);
    renderSection(hash || DATA.sections[0].num);
  </script>
</body>
</html>
''')

html = tpl.substitute(
    total=total,
    nav_html=''.join(nav_html),
    payload_json=payload_json,
