def clip_end_of_section(
    page: fitz.Page,
    left: float,
    top: float,
    right: float,
    bottom: float,
    *,
    gap: float = 4.0,
) -> float:
    """Raise bottom so 'END OF SECTION A' (and similar) is not included."""
    markers = (
