        for rect in page.search_for(marker):
            if rect.y0 < top or rect.y0 > bottom:
                continue
            if rect.x1 < left - 20 or rect.x0 > right + 20:
                continue
            limit = min(limit, float(rect.y0) - gap)
    return max(top + 1.0, limit)


