        f"{record['Statement'][:1800]}\n\n"
        'JSON only: {"sections":[<primary>, ...], "reason":"<one short sentence>"}'
    )
    content = chat(
        [
            {"role": "system", "content": SYSTEM_PROMPT},
            {"role": "user", "content": user},
        ],
        key=key,
