def find_starts_on_image(image: Image.Image, max_questions: int) -> list[tuple[int, float]]:
    """Return (question_number, y_px) on one displayed page image."""
    w, h = image.size
    # Skip the far-left vertical margin warning; numbers sit just inside it.
    # Keep strip wide enough that "1. In a restaurant..." stays on one OCR line.
    strip = image.crop((int(w * 0.035), int(h * 0.035), int(w * 0.32), int(h * 0.96)))
    strip = strip.resize((strip.width * 2, strip.height * 2))
    hits: list[tuple[int, float, float]] = []

    for row in ocr_tsv(strip):
        if row["conf"] < 15:
            continue
        match = match_question_number(row["text"])
        if not match:
            # Starred LQ: "*2." as a single token
            starred = re.fullmatch(r"\*(\d{1,2})\s*[.)]?", _normalize_qnum_text(row["text"]))
            if starred:
                match = starred
            else:
                continue
        qn = int(match.group(1))
        if not (1 <= qn <= max_questions):
            continue
        if row["left"] > strip.width * 0.55:
            continue
        y = int(h * 0.035) + row["top"] / 2.0
        hits.append((qn, y, row["conf"]))

    tsv_qns = {qn for qn, _, _ in hits}
    buf = io.BytesIO()
    strip.save(buf, format="PNG")
    result = subprocess.run(
        ["tesseract", "stdin", "stdout", "--psm", "6"],
        input=buf.getvalue(),
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        check=False,
    )
    text = result.stdout.decode("utf-8", errors="ignore")
    lines = text.splitlines()
    # Box frame often OCRs as | / ] / I / l before the number.
    # Accept: "1. (a)", "1. Capital...", bare "1." / "*2.", "1. Figure..."
    line_q_re = re.compile(
        r"^[|\[\]Il\"'*#\s]*\*?\s*(\d{1,2})\s*[.)]\s*(?:\(|[A-Z*\"'Ff]|$)"
    )
    for i, line in enumerate(lines):
        m = line_q_re.match(line.strip())
        if not m:
            continue
        qn = int(m.group(1))
        if not (1 <= qn <= max_questions) or qn in tsv_qns:
            continue
        # Prefer a real y from a nearby TSV digit / "(a)" rather than line index.
        y = int(h * 0.035) + (i / max(1, len(lines))) * (h * 0.92)
        hits.append((qn, y, 25.0))

    best: dict[int, tuple[float, float]] = {}
    for qn, y, conf in hits:
        prev = best.get(qn)
        if prev is None or y < prev[0] or (y == prev[0] and conf > prev[1]):
            best[qn] = (y, conf)
    return sorted(((qn, best[qn][0]) for qn in best), key=lambda t: t[1])

