      padding: 8px 10px; cursor: pointer; margin-bottom: 2px;
    }}
    .nav-sec:hover {{ background: rgba(255,255,255,0.05); }}
    .nav-sec.active {{ background: rgba(212,165,116,0.16); outline: 1px solid rgba(212,165,116,0.35); }}
