def longest_question_chain(
    candidates: list[tuple[int, int, int]], max_questions: int
) -> list[tuple[int, int, int]]:
    """Prefer a run starting at Q1; else the longest contiguous run."""
    first: dict[int, tuple[int, int, int]] = {}
    for qn, page_i, y in candidates:
        if qn not in first:
            first[qn] = (qn, page_i, y)

    def chain_from(start: int) -> list[tuple[int, int, int]]:
        out: list[tuple[int, int, int]] = []
        q = start
        while q in first and q <= max_questions:
            out.append(first[q])
            q += 1
        return out

    from_one = chain_from(1)
    if from_one:
        return from_one

    best: list[tuple[int, int, int]] = []
    for start in range(2, max_questions + 1):
        chain = chain_from(start)
        if len(chain) > len(best):
