def parse_heading_questions(body: str) -> dict[str, str]:
    out: dict[str, str] = {}
    for qm in QUESTION_RE.finditer(body):
        qn = qm.group(1)
        block = qm.group(2).strip()
        pm = PERF_LINE_RE.search(block)
        if pm:
            note = _clean(pm.group(1))
        else:
