def longest_question_chain(
    candidates: list[tuple[int, int, int]], max_questions: int
) -> list[tuple[int, int, int]]:
    """Prefer ascending Q1..Qn in reading order; allow small gaps."""
    ordered = sorted(
        (c for c in candidates if 1 <= c[0] <= max_questions),
        key=lambda t: (t[1], t[2], t[0]),
    )
    if not ordered:
        return []
    # Greedy: keep first sighting of each qn that is >= previous qn - 0
    # and does not jump backward more than a page after a higher qn started.
    chosen: list[tuple[int, int, int]] = []
    seen: set[int] = set()
    for qn, page_i, y in ordered:
        if qn in seen:
            continue
        if chosen and qn < chosen[-1][0]:
            # Ignore late false positives (e.g. Paper 2 "1."/"2.").
            continue
        chosen.append((qn, page_i, y))
        seen.add(qn)
    return chosen

