def longest_question_chain(
    candidates: list[tuple[int, int, int]], max_questions: int
) -> list[tuple[int, int, int]]:
    """First sighting of each Q in reading order (gaps allowed).

    Paper 2 pages should already be excluded by is_paper_2_page. If a later
    false low-Q appears after a high-Q, drop trailing backward jumps.
    """
    ordered = sorted(
        (c for c in candidates if 1 <= c[0] <= max_questions),
        key=lambda t: (t[1], t[2], t[0]),
    )
    first: dict[int, tuple[int, int, int]] = {}
    for qn, page_i, y in ordered:
        if qn not in first:
            first[qn] = (qn, page_i, y)
    starts = sorted(first.values(), key=lambda t: (t[1], t[2], t[0]))
    if not starts:
        return []
    # Trim trailing backward jumps (Paper 2 "1."/"2." that slipped through).
    trimmed = [starts[0]]
    max_q = starts[0][0]
    for item in starts[1:]:
        qn = item[0]
        if qn < max_q - 1 and qn <= 4 and max_q >= 8:
            break
        trimmed.append(item)
        max_q = max(max_q, qn)
    return trimmed

